-- BuildBack database schema (MySQL 8, InnoDB)
-- Generated by Hibernate from the JPA entities in buildback-backend/src/main/java/com/buildback/entity
-- The application creates/updates these tables itself (spring.jpa.hibernate.ddl-auto=update).
-- This file documents the schema; to create it by hand: CREATE DATABASE buildback_db; USE buildback_db; then run this file.
--
-- users      : accounts (password stored only as a BCrypt hash)
-- materials  : listings; available_quantity = can be ordered, reserved_quantity = held for unpaid orders
-- orders     : one listing per order, price snapshot, 15-minute reservation (expires_at)
-- payments   : payment attempts per order; provider_payment_id is UNIQUE so a payment counts once


    create table materials (
        available_quantity integer not null,
        reserved_quantity integer default 0 not null,
        tile_length_feet decimal(5,2),
        tile_width_feet decimal(5,2),
        unit_price decimal(10,2) not null,
        created_at datetime(6) not null,
        id bigint not null auto_increment,
        seller_id bigint not null,
        updated_at datetime(6) not null,
        version bigint not null,
        city varchar(100) not null,
        title varchar(120) not null,
        description varchar(2000) not null,
        image_url varchar(2048),
        category enum ('FITTINGS','PAINT','PLYWOOD','TILES') not null,
        status enum ('ACTIVE','ARCHIVED') not null,
        unit enum ('CAN','PIECE','SHEET') not null,
        primary key (id)
    ) engine=InnoDB;

    create table orders (
        quantity integer not null,
        total_amount decimal(15,2) not null,
        unit_price decimal(10,2) not null,
        buyer_id bigint not null,
        collected_at datetime(6),
        created_at datetime(6) not null,
        expires_at datetime(6) not null,
        id bigint not null auto_increment,
        material_id bigint not null,
        paid_at datetime(6),
        updated_at datetime(6) not null,
        version bigint not null,
        status enum ('CANCELLED','COLLECTED','EXPIRED','PAID','PENDING_PAYMENT') not null,
        primary key (id)
    ) engine=InnoDB;

    create table payments (
        amount decimal(15,2) not null,
        currency varchar(3) not null,
        refund_required bit not null,
        created_at datetime(6) not null,
        id bigint not null auto_increment,
        order_id bigint not null,
        verified_at datetime(6),
        provider_order_id varchar(100) not null,
        provider_payment_id varchar(100),
        failure_reason varchar(500),
        provider enum ('RAZORPAY','SIMULATOR') not null,
        status enum ('CREATED','FAILED','SUCCESS') not null,
        primary key (id)
    ) engine=InnoDB;

    create table users (
        created_at datetime(6) not null,
        id bigint not null auto_increment,
        name varchar(100) not null,
        email varchar(254) not null,
        password_hash varchar(255) not null,
        role enum ('ADMIN','BUYER','SELLER') not null,
        primary key (id)
    ) engine=InnoDB;

    create index idx_materials_status_created
       on materials (status, created_at);

    create index idx_materials_status_category
       on materials (status, category);

    create index idx_materials_status_price
       on materials (status, unit_price);

    create index idx_materials_seller_status
       on materials (seller_id, status);

    create index idx_orders_buyer_created
       on orders (buyer_id, created_at);

    create index idx_orders_material
       on orders (material_id);

    create index idx_orders_status_expires
       on orders (status, expires_at);

    alter table payments
       add constraint uk_payments_provider_order unique (provider_order_id);

    alter table payments
       add constraint uk_payments_provider_payment unique (provider_payment_id);

    alter table users
       add constraint uk_users_email unique (email);

    alter table materials
       add constraint fk_materials_seller
       foreign key (seller_id)
       references users (id);

    alter table orders
       add constraint fk_orders_buyer
       foreign key (buyer_id)
       references users (id);

    alter table orders
       add constraint fk_orders_material
       foreign key (material_id)
       references materials (id);

    alter table payments
       add constraint fk_payments_order
       foreign key (order_id)
       references orders (id);
